module TeukolskyTransformation

using StaticArrays

export r_to_x, x_to_r, Tx
export Delta, Vr, d2R
export calculate_q1_q2, d2P, calculate_q3_q4, calculate_q5_q6, _relative_residual
export contour_q1, contour_q2
export evaluate_inverse_power_series, evaluate_frobenius_series
export GSN_to_Y_coeffs_minus2_in, GSN_to_Y_coeffs_plus2_up, GSN_to_Y_solution_from_matrix
export P_to_GSN_coefficients_from_matrix

function r_to_x(r, r_plus, r_minus)
    return (r_plus - r) / (r_plus - r_minus)
end

function r_to_x(r, kappa)
    return (1 + kappa - r) / (2 * kappa)
end

function x_to_r(x, r_plus, r_minus)
    return r_plus - x * (r_plus - r_minus)
end

function x_to_r(x, kappa)
    return 1 + kappa - 2 * x * kappa
end

function Delta(r, a)
    return r^2 + a^2 - 2 * r
end

@inline _is_complex_frequency(omega) = !(omega isa Real)

# Kerr P -> GSN coefficient formulas for real frequencies, generated by computer algebra.
# They exclude the common Teukolsky prefactor T(x).
@inline _power(x, y) = x^y



function _P_to_GSN_coefficients_kerr(s::Int, m::Int, a, omega, lambda, r)

    af = Float64(a)

    omegaf = Float64(omega)

    lambdaf = Float64(lambda)

    rf = Float64(r)

    if s == 0

        return _P_to_GSN_coeffs_s0(af, omegaf, m, lambdaf, rf)

    elseif s == 1

        return _P_to_GSN_coeffs_s1(af, omegaf, m, lambdaf, rf)

    elseif s == -1

        return _P_to_GSN_coeffs_sminus1(af, omegaf, m, lambdaf, rf)

    elseif s == 2

        return _P_to_GSN_coeffs_s2(af, omegaf, m, lambdaf, rf)

    elseif s == -2

        return _P_to_GSN_coeffs_sminus2(af, omegaf, m, lambdaf, rf)

    else

        error("unsupported spin")

    end

end



function _P_to_GSN_coeffs_s0(a, omega, m, lambda, r)
    A0 = sqrt(_power(a,2) + _power(r,2))
    A1 = 0
    B0 = ((_power(a,2) + (-2 + r)*r)*(2*r - ((_power(a,2) + _power(r,2))*(complex(0,-4)*omega + complex(0,2)*sqrt(1 - _power(a,2))*omega + (complex(0,2)*(-1 + r)*(-(a*m) + 2*omega*r))/(_power(a,2) + (-2 + r)*r)))/sqrt(1 - _power(a,2))))/(2.0*_power(_power(a,2) + _power(r,2),1.5))
    B1 = -0.5*(_power(a,2) + (-2 + r)*r)/sqrt(-((-1 + _power(a,2))*(_power(a,2) + _power(r,2))))
    return A0, A1, B0, B1
end

