*lambda - complex(0,4)*(-1 + sqrt(1 - _power(a,2)))*omega)*r + (-4 - 4*sqrt(1 - _power(a,2)) - 3*sqrt(1 - _power(a,2))*lambda + 2*(1 + sqrt(1 - _power(a,2)))*_power(m,2) - complex(0,13)*omega + complex(0,9)*sqrt(1 - _power(a,2))*omega)*_power(r,2) + (2 - 2*_power(m,2) + complex(0,4)*omega + 6*(-1 + sqrt(1 - _power(a,2)))*_power(omega,2))*_power(r,3) + 3*omega*(complex(0,-1) + 2*omega)*_power(r,4)))/(sqrt(1 - _power(a,2))*_power(r,3)*_power(_power(a,2) + _power(r,2),1.5))
    B1 = (complex(0,-0.5)*(_power(a,2) + (-2 + r)*r)*(-(_power(a,3)*m*r) - a*m*_power(r,3) + omega*_power(r,5) + _power(a,4)*(complex(0,2) + omega*r) + 2*_power(a,2)*r*(complex(0,-2) + r*(complex(0,1) + omega*r))))/(_power(r,3)*sqrt(-((-1 + _power(a,2))*(_power(a,2) + _power(r,2)))))
