function _P_to_GSN_coeffs_sminus1(a, omega, m, lambda, r)
    A0 = (sqrt((_power(a,2) + _power(r,2))/(1 - _power(a,2)))*(_power(a,4)*(-1 - complex(0,2)*(-1 + sqrt(1 - _power(a,2)))*omega) + complex(0,1)*_power(a,3)*m*(-1 + sqrt(1 - _power(a,2)) + r) + complex(0,1)*a*m*_power(r,2)*(-1 + sqrt(1 - _power(a,2)) + r) + _power(r,2)*(1 + sqrt(1 - _power(a,2)) - complex(0,2)*omega*r*(1 - sqrt(1 - _power(a,2)) + sqrt(1 - _power(a,2))*r)) + _power(a,2)*(1 - sqrt(1 - _power(a,2)) - _power(r,2) - complex(0,2)*omega*r*(1 - sqrt(1 - _power(a,2)) - r + 2*sqrt(1 - _power(a,2))*r))))/(_power(r,2)*(_power(a,2) + (-2 + r)*r))
