4 - 2*sqrt(1 - _power(a,2)) + 3*sqrt(1 - _power(a,2))*lambda - 2*(-1 + sqrt(1 - _power(a,2)))*_power(m,2) + complex(0,13)*omega - complex(0,23)*sqrt(1 - _power(a,2))*omega)*_power(r,2) - 2*(-1 + _power(m,2) - complex(0,2)*(-1 + 3*sqrt(1 - _power(a,2)))*omega - 3*(-1 + sqrt(1 - _power(a,2)))*_power(omega,2))*_power(r,3) + 3*omega*(complex(0,1) + (2 - 4*sqrt(1 - _power(a,2)))*omega)*_power(r,4)) + _power(r,6)*(sqrt(1 - _power(a,2))*lambda*(-2 + r) - omega*r*(complex(0,1)*(1 + sqrt(1 - _power(a,2))) + 2*omega*r*(1 - sqrt(1 - _power(a,2)) + sqrt(1 - _power(a,2))*r))))/(_power(r,3)*(_power(a,2) + (-2 + r)*r)*sqrt(-((-1 + _power(a,2))*_power(_power(a,2) + _power(r,2),3))))
